1	// nxeon-shipper is a tiny, dependency-free telemetry agent installed on every
2	// Nxeon-provisioned VPS/game server via cloud-init (see worker/index.ts
3	// buildCloudInit()). It watches two local sources:
4	//
5	//  1. SSH auth events, via `journalctl -u ssh/sshd -f` (falls back to tailing
6	//     /var/log/auth.log on images that don't run journald-backed sshd logging).
7	//  2. A web server access log, if one happens to be running on the box
8	//     (nginx / apache2 / caddy — checked by path, first match wins). Most
9	//     bare VPS instances don't run one; that's fine, this part is skipped.
10	//
11	// Events are batched and shipped over HTTPS to the Nxeon ingestion endpoint,
12	// authenticated with a per-server bearer token minted at provision time
13	// (see lib/telemetry-token.ts). The agent is deliberately conservative about
14	// resources: everything is a handful of goroutines, log tailing is a cheap
15	// poll loop (no inotify dependency), and the outbound buffer is a small ring
16	// that drops the OLDEST events first under sustained backpressure rather than
17	// growing unbounded or blocking the tailers. If the ingest endpoint is down,
18	// the agent just keeps sampling and quietly drops what doesn't fit — it never
19	// blocks, panics, or spikes CPU retrying.
20	//
21	// Build: CGO_ENABLED=0 go build -ldflags="-s -w" -o nxeon-shipper .
22	// (static binary, no libc dependency, cross-compiles trivially with
23	// GOOS/GOARCH — see agent/nxeon-shipper/build.sh)
24	package main
25	
26	import (
27		"bufio"
28		"bytes"
29		"context"
30		"encoding/json"
31		"fmt"
32		"io"
33		"log"
34		"net/http"
35		"os"
36		"os/exec"
37		"path/filepath"
38		"regexp"
39		"strings"
40		"sync"
41		"time"
42	)
43	
44	// ---- Config -----------------------------------------------------------
45	
46	const (
47		configPath      = "/etc/nxeon/shipper.json"
48		maxBufferedEvts = 2000 // ring cap; oldest dropped first under backpressure
49		batchMaxEvents  = 50
50		batchInterval   = 3 * time.Second
51		httpTimeout     = 8 * time.Second
52	)
53	
54	// Config is written once by cloud-init at provision time. NodeKind is one of
55	// VPS | GAME | HOSTING | MAIL (HOSTING/MAIL are used by the centralized
56	// per-node deployment, not the per-server cloud-init path, but the binary is
57	// identical either way — only the config differs).
58	type Config struct {
59		ServerID  string `json:"server_id"`
60		Token     string `json:"token"`
61		IngestURL string `json:"ingest_url"`
62		NodeKind  string `json:"node_kind"`
63		Label     string `json:"label"` // hostname / display label for the admin UI
64	}
65	
66	func loadConfig() (*Config, error) {
67		b, err := os.ReadFile(configPath)
68		if err != nil {
69			return nil, fmt.Errorf("read %s: %w", configPath, err)
70		}
71		var c Config
72		if err := json.Unmarshal(b, &c); err != nil {
73			return nil, fmt.Errorf("parse %s: %w", configPath, err)
74		}
75		if c.ServerID == "" || c.Token == "" || c.IngestURL == "" {
76			return nil, fmt.Errorf("%s missing server_id/token/ingest_url", configPath)
77		}
78		if c.NodeKind == "" {
79			c.NodeKind = "VPS"
80		}
81		return &c, nil
82	}
83	
84	// ---- Event shape (mirrors lib/telemetry.ts EventIn on the server) -----
85	
86	type Event struct {
87		Type   string `json:"type"`           // SSH_LOGIN | SSH_LOGOUT | SSH_FAILED | VISITOR | MAIL_AUTH
88		TS     string `json:"ts"`             // RFC3339
89		IP     string `json:"ip,omitempty"`
90		User   string `json:"user,omitempty"` // ssh username, or "" for visitor events
91		Path   string `json:"path,omitempty"` // request path for VISITOR events
92		Status string `json:"status,omitempty"`
93		Meta   string `json:"meta,omitempty"` // free-form extra (method, UA, port...)
94		// Site distinguishes which vhost/customer a VISITOR event belongs to on a
95		// centralized (HOSTING) node running one shipper for many customer sites.
96		Site string `json:"site,omitempty"`
97	}
98	
99	// ---- Ring buffer + batching sender --------------------------------------
100	
101	type ring struct {
102		mu   sync.Mutex
103		buf  []Event
104		cap  int
105	}
106	
107	func newRing(cap int) *ring { return &ring{buf: make([]Event, 0, cap), cap: cap} }
108	
109	func (r *ring) push(e Event) {
110		r.mu.Lock()
111		defer r.mu.Unlock()
112		if len(r.buf) >= r.cap {
113			// Drop the oldest quarter to make room, rather than dropping one at a
114			// time under sustained pressure (cheaper than a per-event shift).
115			drop := r.cap / 4
116			if drop < 1 {
117				drop = 1
118			}
119			r.buf = append(r.buf[:0], r.buf[drop:]...)
120		}
121		r.buf = append(r.buf, e)
122	}
123	
124	// drain removes up to n events (oldest first) and returns them.
125	func (r *ring) drain(n int) []Event {
126		r.mu.Lock()
127		defer r.mu.Unlock()
128		if n > len(r.buf) {
129			n = len(r.buf)
130		}
131		if n == 0 {
132			return nil
133		}
134		out := make([]Event, n)
135		copy(out, r.buf[:n])
136		r.buf = append(r.buf[:0], r.buf[n:]...)
137		return out
138	}
139	
140	type batchPayload struct {
141		ServerID string  `json:"server_id"`
142		NodeKind string  `json:"node_kind"`
143		Label    string  `json:"label"`
144		Events   []Event `json:"events"`
145	}
146	
147	func sender(ctx context.Context, cfg *Config, r *ring) {
148		client := &http.Client{Timeout: httpTimeout}
149		backoff := time.Second
150		const maxBackoff = 30 * time.Second
151		ticker := time.NewTicker(batchInterval)
152		defer ticker.Stop()
153		for {
154			select {
155			case <-ctx.Done():
156				return
157			case <-ticker.C:
158			}
159			evts := r.drain(batchMaxEvents)
160			if len(evts) == 0 {
161				continue
162			}
163			payload := batchPayload{ServerID: cfg.ServerID, NodeKind: cfg.NodeKind, Label: cfg.Label, Events: evts}
164			body, err := json.Marshal(payload)
165			if err != nil {
166				continue
167			}
168			req, err := http.NewRequestWithContext(ctx, http.MethodPost, cfg.IngestURL, bytes.NewReader(body))
169			if err != nil {
170				continue
171			}
172			req.Header.Set("Content-Type", "application/json")
173			req.Header.Set("Authorization", "Bearer "+cfg.Token)
174			resp, err := client.Do(req)
175			if err != nil || resp.StatusCode >= 300 {
176				if resp != nil {
177					resp.Body.Close()
178				}
179				// Endpoint unreachable / rejecting: DON'T requeue (that's how a
180				// slow backend turns into unbounded memory growth on the guest);
181				// the events are simply lost, matching the "buffer briefly and
182				// drop old events" resilience requirement. Back off so a downed
183				// ingest endpoint doesn't turn into a retry storm across every
184				// customer VM at once.
185				if backoff < maxBackoff {
186					backoff *= 2
187					if backoff > maxBackoff {
188						backoff = maxBackoff
189					}
190				}
191				select {
192				case <-ctx.Done():
193					return
194				case <-time.After(backoff):
195				}
196				continue
197			}
198			resp.Body.Close()
199			backoff = time.Second
200		}
201	}
202	
203	// ---- SSH auth tailing ----------------------------------------------------
204	
205	var (
206		reAccepted   = regexp.MustCompile(`Accepted (\S+) for (\S+) from (\S+) port (\d+)`)
207		reFailed     = regexp.MustCompile(`Failed (\S+) for (?:invalid user )?(\S+) from (\S+) port (\d+)`)
208		reDisconnect = regexp.MustCompile(`Disconnected from (?:user (\S+) )?(\S+) port (\d+)`)
209		reClosed     = regexp.MustCompile(`session closed for user (\S+)`)
210	)
211	
212	func classifySSHLine(line string) *Event {
213		now := time.Now().UTC().Format(time.RFC3339)
214		if m := reAccepted.FindStringSubmatch(line); m != nil {
215			return &Event{Type: "SSH_LOGIN", TS: now, User: m[2], IP: m[3], Status: "ok", Meta: "method=" + m[1]}
216		}
217		if m := reFailed.FindStringSubmatch(line); m != nil {
218			return &Event{Type: "SSH_FAILED", TS: now, User: m[2], IP: m[3], Status: "failed", Meta: "method=" + m[1]}
219		}
220		if m := reClosed.FindStringSubmatch(line); m != nil {
221			return &Event{Type: "SSH_LOGOUT", TS: now, User: m[1], Status: "ok"}
222		}
223		if m := reDisconnect.FindStringSubmatch(line); m != nil {
224			user := m[1]
225			return &Event{Type: "SSH_LOGOUT", TS: now, User: user, IP: m[2], Status: "ok"}
226		}
227		return nil
228	}
229	
230	// tailSSHJournal follows `journalctl -u <unit> -f` for whichever sshd unit
231	// name actually exists on this image (ssh.service on Debian/Ubuntu,
232	// sshd.service on RHEL-family), restarting the subprocess if it dies. Falls
233	// back to tailing /var/log/auth.log if journalctl isn't usable at all (e.g.
234	// image without persistent journald), so the feature degrades rather than
235	// silently doing nothing.
236	func tailSSHJournal(ctx context.Context, r *ring) {
237		unit := detectSSHUnit()
238		if unit == "" {
239			tailFile(ctx, r, "/var/log/auth.log", classifySSHLine)
240			return
241		}
242		for {
243			if ctx.Err() != nil {
244				return
245			}
246			cmd := exec.CommandContext(ctx, "journalctl", "-u", unit, "-f", "-n", "0", "-o", "cat")
247			stdout, err := cmd.StdoutPipe()
248			if err != nil {
249				time.Sleep(5 * time.Second)
250				continue
251			}
252			if err := cmd.Start(); err != nil {
253				time.Sleep(5 * time.Second)
254				continue
255			}
256			scanner := bufio.NewScanner(stdout)
257			scanner.Buffer(make([]byte, 0, 4096), 64*1024)
258			for scanner.Scan() {
259				if e := classifySSHLine(scanner.Text()); e != nil {
260					r.push(*e)
261				}
262			}
263			_ = cmd.Wait()
264			if ctx.Err() != nil {
265				return
266			}
267			time.Sleep(3 * time.Second) // journalctl exited (e.g. journald restart); retry
268		}
269	}
270	
271	func detectSSHUnit() string {
272		for _, unit := range []string{"ssh.service", "sshd.service"} {
273			cmd := exec.Command("systemctl", "is-enabled", unit)
274			if err := cmd.Run(); err == nil {
275				return unit
276			}
277			cmd2 := exec.Command("systemctl", "is-active", unit)
278			if err := cmd2.Run(); err == nil {
279				return unit
280			}
281		}
282		// journalctl itself may still work even if the enabled-check above didn't
283		// match; try a cheap direct probe as a last resort.
284		if out, err := exec.Command("journalctl", "-u", "ssh.service", "-n", "1").CombinedOutput(); err == nil && len(out) > 0 {
285			return "ssh.service"
286		}
287		if out, err := exec.Command("journalctl", "-u", "sshd.service", "-n", "1").CombinedOutput(); err == nil && len(out) > 0 {
288			return "sshd.service"
289		}
290		return ""
291	}
292	
293	// tailFile polls a plain log file for new lines (append-only tail -f
294	// semantics without needing inotify), handling rotation by re-opening when
295	// the inode shrinks or disappears. classify turns a raw line into an *Event
296	// (nil to skip).
297	func tailFile(ctx context.Context, r *ring, path string, classify func(string) *Event) {
298		var f *os.File
299		var reader *bufio.Reader
300		var lastSize int64
301	
302		open := func() bool {
303			var err error
304			f, err = os.Open(path)
305			if err != nil {
306				return false
307			}
308			fi, err := f.Stat()
309			if err != nil {
310				f.Close()
311				return false
312			}
313			lastSize = fi.Size()
314			// Start at EOF: we only care about NEW events from process start
315			// onward, not the whole historical file.
316			if _, err := f.Seek(0, io.SeekEnd); err != nil {
317				f.Close()
318				return false
319			}
320			reader = bufio.NewReader(f)
321			return true
322		}
323	
324		ticker := time.NewTicker(750 * time.Millisecond)
325		defer ticker.Stop()
326		for {
327			select {
328			case <-ctx.Done():
329				if f != nil {
330					f.Close()
331				}
332				return
333			case <-ticker.C:
334			}
335			if f == nil {
336				if !open() {
337					continue // file doesn't exist (yet, or never will) — keep polling cheaply
338				}
339			}
340			fi, err := os.Stat(path)
341			if err != nil {
342				f.Close()
343				f = nil
344				continue
345			}
346			if fi.Size() < lastSize {
347				// Rotated/truncated: reopen from start of new file.
348				f.Close()
349				f = nil
350				if !open() {
351					continue
352				}
353			}
354			for {
355				line, err := reader.ReadString('\n')
356				if line != "" {
357					if e := classify(strings.TrimRight(line, "\r\n")); e != nil {
358						r.push(*e)
359					}
360				}
361				if err != nil {
362					break
363				}
364			}
365			if newFi, err := f.Stat(); err == nil {
366				lastSize = newFi.Size()
367			}
368		}
369	}
370	
371	// ---- Web access log detection + parsing ---------------------------------
372	
373	// combined/common log format: IP - - [ts] "METHOD /path HTTP/x" status size
374	var reAccessCombined = regexp.MustCompile(`^(\S+) \S+ \S+ \[[^\]]+\] "(\S+) (\S+) \S+" (\d{3}) `)
375	
376	func classifyAccessLine(line string) *Event {
377		m := reAccessCombined.FindStringSubmatch(line)
378		if m == nil {
379			return nil
380		}
381		return &Event{
382			Type:   "VISITOR",
383			TS:     time.Now().UTC().Format(time.RFC3339),
384			IP:     m[1],
385			Path:   m[3],
386			Status: m[4],
387			Meta:   "method=" + m[2],
388		}
389	}
390	
391	// candidateAccessLogs are checked in order; first one that exists wins. This
392	// intentionally only covers the single-tenant "one web server on this box"
393	// case (VPS/game server). The centralized HOSTING deployment tails a
394	// per-vhost log set instead (see watchHostingVhosts).
395	var candidateAccessLogs = []string{
396		"/var/log/nginx/access.log",
397		"/var/log/apache2/access.log",
398		"/var/log/caddy/access.log",
399		"/var/log/httpd/access_log",
400	}
401	
402	func detectAccessLog() string {
403		for _, p := range candidateAccessLogs {
404			if fi, err := os.Stat(p); err == nil && !fi.IsDir() {
405				return p
406			}
407		}
408		return ""
409	}
410	
411	// ---- Centralized HOSTING mode: many vhost logs on one node ---------------
412	
413	// hostingLogGlob matches per-account/per-site nginx logs written by
414	// worker/hosting.ts (see NOTE in commit message: today's shared-hosting
415	// vhosts don't set a per-account access_log directive, so this glob also
416	// covers the platform-wide default log as a fallback "site" named "_default").
417	const hostingLogDir = "/var/log/nginx"
418	
419	func watchHostingVhosts(ctx context.Context, r *ring) {
420		seen := map[string]bool{}
421		var wg sync.WaitGroup
422		scan := func() {
423			entries, err := os.ReadDir(hostingLogDir)
424			if err != nil {
425				return
426			}
427			for _, e := range entries {
428				if e.IsDir() || !strings.HasSuffix(e.Name(), "access.log") {
429					continue
430				}
431				p := filepath.Join(hostingLogDir, e.Name())
432				if seen[p] {
433					continue
434				}
435				seen[p] = true
436				site := strings.TrimSuffix(e.Name(), ".access.log")
437				wg.Add(1)
438				go func(path, site string) {
439					defer wg.Done()
440					tailFile(ctx, r, path, func(line string) *Event {
441						e := classifyAccessLine(line)
442						if e != nil {
443							e.Site = site
444						}
445						return e
446					})
447				}(p, site)
448			}
449		}
450		scan()
451		ticker := time.NewTicker(30 * time.Second) // pick up newly provisioned sites
452		defer ticker.Stop()
453		for {
454			select {
455			case <-ctx.Done():
456				wg.Wait()
457				return
458			case <-ticker.C:
459				scan()
460			}
461		}
462	}
463	
464	// ---- Centralized MAIL mode: Dovecot/Postfix auth log ---------------------
465	
466	var reMailAuth = regexp.MustCompile(`(?:dovecot|postfix/smtpd).*?(?:Login|login): user=<([^>]*)>.*?rip=([0-9a-fA-F:.]+)|(?:dovecot).*?auth failed.*?user=<([^>]*)>.*?rip=([0-9a-fA-F:.]+)`)
467	
468	func classifyMailLine(line string) *Event {
469		lower := strings.ToLower(line)
470		if !strings.Contains(lower, "dovecot") && !strings.Contains(lower, "postfix") {
471			return nil
472		}
473		m := reMailAuth.FindStringSubmatch(line)
474		if m == nil {
475			return nil
476		}
477		now := time.Now().UTC().Format(time.RFC3339)
478		if m[1] != "" {
479			return &Event{Type: "MAIL_AUTH", TS: now, User: m[1], IP: m[2], Status: "ok"}
480		}
481		return &Event{Type: "MAIL_AUTH", TS: now, User: m[3], IP: m[4], Status: "failed"}
482	}
483	
484	// ---- main -----------------------------------------------------------------
485	
486	func main() {
487		cfg, err := loadConfig()
488		if err != nil {
489			log.Fatalf("nxeon-shipper: %v", err)
490		}
491	
492		ctx, cancel := context.WithCancel(context.Background())
493		defer cancel()
494	
495		r := newRing(maxBufferedEvts)
496		go sender(ctx, cfg, r)
497	
498		switch cfg.NodeKind {
499		case "HOSTING":
500			go watchHostingVhosts(ctx, r)
501		case "MAIL":
502			// Mailcow's postfix/dovecot logs land in the mail node's own journal
503			// under docker's forwarding; mailcow-compose ships a "postfix-mailcow"
504			// / "dovecot-mailcow" container. We tail the host-side syslog file
505			// mailcow's vmail-stats/rsyslog forwards to, which is the simplest
506			// integration that doesn't require joining the docker network.
507			go tailFile(ctx, r, "/var/log/mail.log", classifyMailLine)
508		default: // VPS, GAME
509			go tailSSHJournal(ctx, r)
510			if p := detectAccessLog(); p != "" {
511				go tailFile(ctx, r, p, classifyAccessLine)
512			}
513			// else: no web server on this box — skip gracefully, per spec.
514		}
515	
516		// Idle CPU/RAM stays negligible: everything above is either blocked on a
517		// subprocess pipe read, a 750ms/30s ticker, or the 3s batch ticker — no
518		// busy loops anywhere.
519		sig := make(chan os.Signal, 1)
520		notifySignals(sig)
521		<-sig
522		cancel()
523		time.Sleep(200 * time.Millisecond) // let sender flush its last drain cycle's HTTP call
524	}
