1	#!/usr/bin/env node
2	"use strict";
3	/**
4	 * Nxeon node-agent — see docs/DOCUMENTATION.md's "Multi-node synergy" section
5	 * for the full design. Runs on every NON-PRIMARY compute node. Gives the
6	 * primary's worker a narrow, token-authenticated way to touch this node's own
7	 * NAT table and cloud-init snippet storage — the two host-level operations
8	 * the worker cannot reach any other way once it isn't running on this box.
9	 *
10	 * DELIBERATELY plain, dependency-free JavaScript (Node built-ins only: http,
11	 * https, fs, child_process, crypto, url) — this ONE file is copied to a
12	 * freshly onboarded node that has no npm packages, no copy of this repo, and
13	 * should need neither. No database access, no Proxmox API token, nothing
14	 * beyond what these operations need — a leaked token's blast radius is NAT
15	 * rules and cloud-init snippets for this one node, never a shell, never data.
16	 *
17	 * AUTH: every request must carry `Authorization: Bearer <token>`, checked by
18	 * constant-time comparison against NXEON_AGENT_TOKEN (env, sourced from
19	 * /etc/nxeon/node-agent.env — the only copy of the plaintext token on this
20	 * machine; the primary's copy is encrypted at rest, see lib/node-agent.ts).
21	 * Network exposure is ADDITIONALLY restricted by this node's own firewall to
22	 * the primary's public IP only (see onboard-node.sh's agent-allow rule) — the
23	 * token is defense in depth on top of that, not the only gate.
24	 *
25	 * TRANSPORT: HTTPS with a self-signed cert generated once at onboard time
26	 * (openssl, no CA involved). The primary connects with certificate
27	 * verification disabled — the SAME trust model this codebase already uses to
28	 * reach this node's own Proxmox API (lib/proxmox.ts's insecureAgent) — which
29	 * still encrypts the token on the wire without needing a CA-issued cert for a
30	 * bare IP with no public DNS name.
31	 *
32	 * Run directly: node node-agent/index.js
33	 * As a service: deploy/nxeon-node-agent.service (installed by onboard-node.sh)
34	 */
35	
36	const https = require("node:https");
37	const fs = require("node:fs");
38	const path = require("node:path");
39	const crypto = require("node:crypto");
40	const { execFile } = require("node:child_process");
41	
42	const PORT = Number(process.env.NXEON_AGENT_PORT || 8943);
43	const TOKEN = process.env.NXEON_AGENT_TOKEN || "";
44	const TLS_KEY = process.env.NXEON_AGENT_TLS_KEY || "/etc/nxeon/node-agent.key.pem";
45	const TLS_CERT = process.env.NXEON_AGENT_TLS_CERT || "/etc/nxeon/node-agent.cert.pem";
46	// Generous enough for any real cloud-init snippet (a few KB of YAML/bash);
47	// bounded so a malformed/malicious body can't exhaust memory.
48	const MAX_BODY_BYTES = 1024 * 1024;
49	const CMD_TIMEOUT_MS = 15_000;
50	
51	if (!TOKEN || TOKEN.length < 20) {
52	  console.error("[node-agent] NXEON_AGENT_TOKEN is missing or suspiciously short — refusing to start. " +
53	    "onboard-node.sh generates a proper one; don't hand-edit /etc/nxeon/node-agent.env with a short value.");
54	  process.exit(1);
55	}
56	if (!Number.isInteger(PORT) || PORT < 1 || PORT > 65535) {
57	  console.error(`[node-agent] NXEON_AGENT_PORT=${process.env.NXEON_AGENT_PORT} is not a valid port — refusing to start.`);
58	  process.exit(1);
59	}
60	
61	// ---- Validation — mirrors lib/nat-rules.ts's own rules; keep in sync ------
62	const IPV4_RE = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
63	const CHAIN_RE = /^[A-Z0-9_]{1,40}$/;
64	const STORAGE_RE = /^[a-zA-Z0-9_-]{1,60}$/;
65	// Matches exactly the filenames worker/index.ts's provision() ever asks for:
66	// nxeon-<vmid>.yaml. Nothing else is ever written or deleted by this agent.
67	const FILENAME_RE = /^nxeon-\d+\.yaml$/;
68	
69	/** True only for an actual string matching `re` — RegExp#test() coerces its
70	 *  argument, so `CHAIN_RE.test(123)` would otherwise pass (stringifies to
71	 *  "123", which matches [A-Z0-9_]) and hand a NUMBER to execFile's argv array
72	 *  a few lines later. Every JSON-body-derived field is checked with this,
73	 *  never a bare `.test()`, so a type-confused value is rejected up front
74	 *  instead of surfacing as a confusing execFile error downstream. */
75	function isStr(v, re) {
76	  return typeof v === "string" && re.test(v);
77	}
78	
79	function isValidPort(n) {
80	  return Number.isInteger(n) && n >= 1 && n <= 65535;
81	}
82	function isValidRule(r) {
83	  return (
84	    !!r &&
85	    (r.proto === "tcp" || r.proto === "udp") &&
86	    isValidPort(r.dport) &&
87	    typeof r.destIp === "string" &&
88	    IPV4_RE.test(r.destIp) &&
89	    isValidPort(r.destPort)
90	  );
91	}
92	/** Argv fragment shared by -A/-D — mirrors lib/nat-rules.ts's ruleSpec(). */
93	function ruleSpec(r) {
94	  return ["-p", r.proto, "--dport", String(r.dport), "-j", "DNAT", "--to-destination", `${r.destIp}:${r.destPort}`];
95	}
96	
97	// ---- constant-time bearer check --------------------------------------------
98	function checkAuth(req) {
99	  const header = req.headers["authorization"] || "";
100	  const m = /^Bearer (.+)$/.exec(header);
101	  if (!m) return false;
102	  const presented = Buffer.from(m[1]);
103	  const expected = Buffer.from(TOKEN);
104	  // timingSafeEqual throws on a length mismatch rather than returning false —
105	  // guard it explicitly so a short/garbled header can't produce a stack trace.
106	  if (presented.length !== expected.length) return false;
107	  return crypto.timingSafeEqual(presented, expected);
108	}
109	
110	// ---- iptables exec — argv arrays only, NEVER a shell string ----------------
111	function iptables(args) {
112	  return new Promise((resolve, reject) => {
113	    execFile("iptables", args, { timeout: CMD_TIMEOUT_MS }, (err, stdout, stderr) => {
114	      if (err) return reject(new Error(String(stderr || err.message).trim().slice(0, 400)));
115	      resolve(stdout);
116	    });
117	  });
118	}
119	
120	async function ensureChain(chain) {
121	  try {
122	    await iptables(["-t", "nat", "-N", chain]);
123	  } catch {
124	    /* chain already exists */
125	  }
126	  try {
127	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", chain]);
128	  } catch {
129	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", chain]);
130	  }
131	}
132	
133	function pvesmPath(storageRef) {
134	  return new Promise((resolve, reject) => {
135	    execFile("pvesm", ["path", storageRef], { timeout: 10_000 }, (err, stdout) => {
136	      if (err) return reject(new Error(`pvesm path ${storageRef}: ${err.message}`));
137	      resolve(stdout.trim());
138	    });
139	  });
140	}
141	
142	// ---- request body helpers ---------------------------------------------------
143	function readBody(req) {
144	  return new Promise((resolve, reject) => {
145	    let size = 0;
146	    const chunks = [];
147	    req.on("data", (c) => {
148	      size += c.length;
149	      if (size > MAX_BODY_BYTES) {
150	        reject(new Error("request body too large"));
151	        req.destroy();
152	        return;
153	      }
154	      chunks.push(c);
155	    });
156	    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
157	    req.on("error", reject);
158	  });
159	}
160	
161	/** Parse a JSON body, or return undefined (never throws) so handlers can 400 cleanly. */
162	function parseJson(text) {
163	  try {
164	    return JSON.parse(text || "{}");
165	  } catch {
166	    return undefined;
167	  }
168	}
169	
170	function sendJson(res, status, obj) {
171	  const body = JSON.stringify(obj);
172	  res.writeHead(status, { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) });
173	  res.end(body);
174	}
175	
176	// ---- route handlers ---------------------------------------------------------
177	
178	async function handleHealth(_req, res) {
179	  sendJson(res, 200, { ok: true, version: 1 });
180	}
181	
182	async function handleEnsureChain(_req, res, rawBody) {
183	  const parsed = parseJson(rawBody);
184	  const chain = parsed && parsed.chain;
185	  if (!parsed || !CHAIN_RE.test(chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
186	  await ensureChain(chain);
187	  sendJson(res, 200, { ok: true });
188	}
189	
190	async function handleListChain(_req, res, chain) {
191	  if (!CHAIN_RE.test(chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
192	  // Deliberately NOT swallowed on failure — reconcileNatChain always calls
193	  // ensure-chain immediately before this, so a real failure here (not "chain
194	  // missing", which can't happen given that ordering) is a genuine problem
195	  // the caller needs to see, exactly like the local iptablesHost() in
196	  // worker/network.ts never special-cases this either.
197	  const output = await iptables(["-t", "nat", "-S", chain]);
198	  sendJson(res, 200, { output });
199	}
200	
201	async function handleAddRule(_req, res, rawBody) {
202	  const parsed = parseJson(rawBody);
203	  if (!parsed || !CHAIN_RE.test(parsed.chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
204	  if (!isValidRule(parsed.rule)) return sendJson(res, 400, { error: "invalid rule" });
205	  await iptables(["-t", "nat", "-A", parsed.chain, ...ruleSpec(parsed.rule)]);
206	  sendJson(res, 200, { ok: true });
207	}
208	
209	async function handleDeleteRule(_req, res, rawBody) {
210	  const parsed = parseJson(rawBody);
211	  if (!parsed || !CHAIN_RE.test(parsed.chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
212	  if (!isValidRule(parsed.rule)) return sendJson(res, 400, { error: "invalid rule" });
213	  await iptables(["-t", "nat", "-D", parsed.chain, ...ruleSpec(parsed.rule)]);
214	  sendJson(res, 200, { ok: true });
215	}
216	
217	/** Resolve `<storage>:snippets/<filename>` via pvesm and refuse anything that
218	 *  didn't land in a real snippets directory — defense in depth beyond the
219	 *  filename/storage allowlists above. */
220	async function resolveSnippetPath(storage, filename) {
221	  const target = await pvesmPath(`${storage}:snippets/${filename}`);
222	  if (!target.includes(`${path.sep}snippets${path.sep}`) && !target.endsWith(`${path.sep}snippets`)) {
223	    throw new Error("storage did not resolve to a snippets path");
224	  }
225	  return target;
226	}
227	
228	async function handleWriteSnippet(_req, res, rawBody) {
229	  const parsed = parseJson(rawBody);
230	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
231	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
232	  if (typeof parsed.content !== "string" || parsed.content.length > MAX_BODY_BYTES) {
233	    return sendJson(res, 400, { error: "invalid content" });
234	  }
235	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
236	  fs.mkdirSync(path.dirname(target), { recursive: true });
237	  fs.writeFileSync(target, parsed.content, { mode: 0o600 });
238	  sendJson(res, 200, { ok: true });
239	}
240	
241	async function handleDeleteSnippet(_req, res, rawBody) {
242	  const parsed = parseJson(rawBody);
243	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
244	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
245	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
246	  fs.rmSync(target, { force: true });
247	  sendJson(res, 200, { ok: true });
248	}
249	
250	async function handleDnatCheck(_req, res, address) {
251	  if (!IPV4_RE.test(address || "")) return sendJson(res, 400, { error: "invalid address" });
252	  const output = await iptables(["-t", "nat", "-S", "PREROUTING"]);
253	  const hasLiveDnatRule = output.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
254	  sendJson(res, 200, { hasLiveDnatRule });
255	}
256	
257	// ---- router ------------------------------------------------------------------
258	
259	async function route(req, res) {
260	  const url = new URL(req.url, `https://${req.headers.host || "localhost"}`);
261	  const { pathname, searchParams } = url;
262	
263	  if (req.method === "GET" && pathname === "/v1/health") return handleHealth(req, res);
264	
265	  if (req.method === "POST" && pathname === "/v1/nat/ensure-chain") return handleEnsureChain(req, res, await readBody(req));
266	
267	  const chainMatch = /^\/v1\/nat\/chain\/([^/]+)$/.exec(pathname);
268	  if (req.method === "GET" && chainMatch) return handleListChain(req, res, decodeURIComponent(chainMatch[1]));
269	
270	  if (req.method === "POST" && pathname === "/v1/nat/rule") return handleAddRule(req, res, await readBody(req));
271	  if (req.method === "DELETE" && pathname === "/v1/nat/rule") return handleDeleteRule(req, res, await readBody(req));
272	
273	  if (req.method === "POST" && pathname === "/v1/snippet") return handleWriteSnippet(req, res, await readBody(req));
274	  if (req.method === "DELETE" && pathname === "/v1/snippet") return handleDeleteSnippet(req, res, await readBody(req));
275	
276	  if (req.method === "GET" && pathname === "/v1/iptables/dnat-check") return handleDnatCheck(req, res, searchParams.get("address"));
277	
278	  sendJson(res, 404, { error: "not found" });
279	}
280	
281	const server = https.createServer({ key: fs.readFileSync(TLS_KEY), cert: fs.readFileSync(TLS_CERT) }, (req, res) => {
282	  if (!checkAuth(req)) {
283	    sendJson(res, 401, { error: "unauthorized" });
284	    return;
285	  }
286	  route(req, res).catch((e) => {
287	    console.error("[node-agent] request error:", e && e.message ? e.message : e);
288	    try {
289	      sendJson(res, 500, { error: String((e && e.message) || e).slice(0, 300) });
290	    } catch {
291	      /* response already sent/closed */
292	    }
293	  });
294	});
295	
296	server.listen(PORT, () => {
297	  console.log(`[node-agent] listening on :${PORT}`);
298	});
299

